CREATE TABLE categories (id text PRIMARY KEY, name text NOT NULL UNIQUE);
CREATE TABLE products (id text PRIMARY KEY, category_id text NOT NULL REFERENCES categories(id), slug text NOT NULL UNIQUE, name text NOT NULL, description text NOT NULL, asset text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE variants (id text PRIMARY KEY, product_id text NOT NULL REFERENCES products(id), sku text NOT NULL UNIQUE, name text NOT NULL, units integer NOT NULL CHECK(units BETWEEN 1 AND 24), price_rial bigint NOT NULL CHECK(price_rial BETWEEN 10 AND 1000000000 AND price_rial % 10=0), active boolean NOT NULL DEFAULT true);
CREATE TABLE warehouses (id text PRIMARY KEY, name text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true);
CREATE TABLE inventory_balances (warehouse_id text REFERENCES warehouses(id), variant_id text REFERENCES variants(id), on_hand integer NOT NULL DEFAULT 0 CHECK(on_hand>=0), reserved integer NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=on_hand), PRIMARY KEY(warehouse_id,variant_id));
CREATE TABLE roles (id text PRIMARY KEY);
CREATE TABLE admin_users (id text PRIMARY KEY, username text NOT NULL UNIQUE, password_hash text NOT NULL, role_id text NOT NULL REFERENCES roles(id), active boolean NOT NULL DEFAULT true);
CREATE TABLE sessions (id text PRIMARY KEY, token_hash text NOT NULL UNIQUE, csrf_token text NOT NULL, admin_id text REFERENCES admin_users(id), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE login_attempts (identity_hash text PRIMARY KEY, failures integer NOT NULL, window_start timestamptz NOT NULL);
CREATE TABLE carts (id text PRIMARY KEY, session_id text NOT NULL UNIQUE REFERENCES sessions(id), revision integer NOT NULL DEFAULT 0);
CREATE TABLE cart_items (cart_id text REFERENCES carts(id) ON DELETE CASCADE, variant_id text REFERENCES variants(id), quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 24), PRIMARY KEY(cart_id,variant_id));
CREATE TABLE orders (id text PRIMARY KEY, session_id text NOT NULL REFERENCES sessions(id), cart_id text NOT NULL REFERENCES carts(id), cart_revision integer NOT NULL, checkout_key text NOT NULL, status text NOT NULL CHECK(status IN ('pending','paid','processing','shipped','cancelled','expired')), total_rial bigint NOT NULL CHECK(total_rial>0), warehouse_id text NOT NULL REFERENCES warehouses(id), created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, UNIQUE(session_id,checkout_key), UNIQUE(cart_id,cart_revision));
CREATE INDEX orders_session_recent ON orders(session_id,created_at DESC,id);
CREATE INDEX orders_status_recent ON orders(status,created_at DESC,id);
CREATE TABLE order_items (order_id text REFERENCES orders(id), variant_id text REFERENCES variants(id), sku text NOT NULL, product_name text NOT NULL, variant_name text NOT NULL, unit_price_rial bigint NOT NULL CHECK(unit_price_rial>0), quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 24), PRIMARY KEY(order_id,variant_id));
CREATE TABLE reservations (id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id), warehouse_id text NOT NULL REFERENCES warehouses(id), variant_id text NOT NULL REFERENCES variants(id), quantity integer NOT NULL CHECK(quantity>0), status text NOT NULL CHECK(status IN ('active','released','consumed')), expires_at timestamptz NOT NULL, UNIQUE(order_id,variant_id));
CREATE INDEX reservations_active_expiry ON reservations(expires_at,order_id) WHERE status='active';
CREATE TABLE payment_attempts (id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id), idempotency_key text NOT NULL, scenario text NOT NULL CHECK(scenario IN ('success','failure','cancel')), status text NOT NULL CHECK(status IN ('succeeded','failed','cancelled')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(order_id,idempotency_key));
CREATE TABLE inventory_movements (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, warehouse_id text NOT NULL, variant_id text NOT NULL, delta integer NOT NULL CHECK(delta<>0), reason text NOT NULL, order_id text REFERENCES orders(id), admin_id text REFERENCES admin_users(id), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(warehouse_id,variant_id) REFERENCES inventory_balances(warehouse_id,variant_id));
CREATE INDEX movements_balance_recent ON inventory_movements(warehouse_id,variant_id,created_at DESC);
CREATE TABLE audit_records (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, admin_id text NOT NULL REFERENCES admin_users(id), action text NOT NULL, entity_id text NOT NULL, detail text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_recent ON audit_records(created_at DESC,id);
CREATE TABLE catalog_revision (id boolean PRIMARY KEY DEFAULT true CHECK(id), revision bigint NOT NULL DEFAULT 1);
